        idx = int(0.95 * len(sorted_times))
        idx = min(idx, len(sorted_times) - 1)
        return sorted_times[idx]

    @property
    def min_ms(self) -> float:
        if not self.times_ms:
            return 0.0
        return min(self.times_ms)

    @property
    def max_ms(self) -> float:
        if not self.times_ms:
            return 0.0
        return max(self.times_ms)

    @property
    def stdev_ms(self) -> float:
        if len(self.times_ms) < 2:
            return 0.0
        return statistics.stdev(self.times_ms)

    @property
    def mean_memory_mb(self) -> float:
        if not self.memory_mb:
            return 0.0
        return statistics.mean(self.memory_mb)

    @property
    def max_memory_mb(self) -> float:
        if not self.memory_mb:
            return 0.0
        return max(self.memory_mb)

    @property
    def success_count(self) -> int:
        return len(self.times_ms)

    @property
    def failure_count(self) -> int:
        return len(self.errors)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "operation_name": self.operation_name,
            "input_size": self.input_size,
            "iterations": self.iterations,
            "mean_ms": self.mean_ms,
            "median_ms": self.median_ms,
            "p95_ms": self.p95_ms,
            "min_ms": self.min_ms,
            "max_ms": self.max_ms,
            "stdev_ms": self.stdev_ms,
            "mean_memory_mb": self.mean_memory_mb,
            "max_memory_mb": self.max_memory_mb,
            "success_count": self.success_count,
            "failure_count": self.failure_count,
            "errors": self.errors,
        }


def measure_performance(
    func: Callable,
    operation_name: str,
    input_size: int,
    iterations: int,
    warmup_iterations: int = 3,
    warmup_input_size: int = 100,
    measure_memory: bool = True,
) -> PerformanceResult:
    """
    Measure the performance of a function over multiple iterations.

    Args:
        func: The function to measure. Should accept an input size parameter.
        operation_name: Name of the operation for reporting.
        input_size: Size of input for each iteration.
        iterations: Number of measurement iterations.
        warmup_iterations: Number of warmup iterations (not measured).
        warmup_input_size: Size of input for warmup iterations.
        measure_memory: Whether to measure memory usage.

    Returns:
        PerformanceResult with all measured metrics.
    """
    result = PerformanceResult(
        operation_name=operation_name,
        input_size=input_size,
        iterations=iterations,
    )

    # Warmup phase
    for _ in range(warmup_iterations):
        try:
            func(warmup_input_size)
        except Exception:
            pass  # Ignore warmup errors

    # Measurement phase
    for i in range(iterations):
        start_time = time.perf_counter()
        memory_before = _get_memory_mb() if measure_memory else 0.0

        try:
            func(input_size)
            elapsed_ms = (time.perf_counter() - start_time) * 1000.0
            result.times_ms.append(elapsed_ms)

            if measure_memory:
                memory_after = _get_memory_mb()
                result.memory_mb.append(max(0.0, memory_after - memory_before))
        except Exception as e:
            elapsed_ms = (time.perf_counter() - start_time) * 1000.0
            result.errors.append(f"Iteration {i}: {type(e).__name__}: {str(e)}")

    return result


def _get_memory_mb() -> float:
    """Get current process memory usage in MB."""
    try:
        import resource
        # On Linux, ru_maxrss is in KB
        usage = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
        if sys.platform == 'darwin':
            # On macOS, ru_maxrss is in bytes
            return usage / (1024 * 1024)
        else:
            # On Linux, ru_maxrss is in KB
            return usage / 1024
    except ImportError:
        try:
            import psutil
            process = psutil.Process()
            return process.memory_info().rss / (1024 * 1024)
        except ImportError:
            return 0.0


